#!/usr/bin/env python3
"""
Generates Fealty's GUI kit: nine-slice window, panel, button, tab and HUD sprites plus 16x16 icons.

Sprites land in src/main/resources/assets/fealty/textures/gui/sprites/, which Minecraft stitches into the GUI
atlas. Nine-slice sprites get a .mcmeta next to them so they scale to any size. Re-run after editing:

    python3 tools/art/generate_ui.py
"""
import json
import os
import random

from PIL import Image

from generate_art import TEX, hexc, shade

SPRITES = os.path.join(TEX, "gui", "sprites")

INK = "#3B2A1A"
LEATHER = "#5D3A1F"
LEATHER_DARK = "#3B2416"
OUTLINE = "#1E120A"
GOLD = "#D4AF37"
GOLD_DARK = "#9C7A1E"
GOLD_LIGHT = "#F2D675"
PARCHMENT = "#E8D9B0"


def write(img, name, scaling=None):
    path = os.path.join(SPRITES, name + ".png")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    img.save(path)
    meta = path + ".mcmeta"
    if scaling is not None:
        with open(meta, "w") as f:
            json.dump({"gui": {"scaling": scaling}}, f, indent=2)
            f.write("\n")
    elif os.path.exists(meta):
        os.remove(meta)


def nine(w, h, border):
    return {"type": "nine_slice", "width": w, "height": h, "border": border}


def canvas(w, h):
    return Image.new("RGBA", (w, h), (0, 0, 0, 0))


def noisy(rand, color, amount):
    return shade(hexc(color) if isinstance(color, str) else color, 1.0 + rand.uniform(-amount, amount))


def parchment_fill(img, x0, y0, x1, y1, rand, base=PARCHMENT, amount=0.03):
    px = img.load()
    for y in range(y0, y1):
        for x in range(x0, x1):
            px[x, y] = noisy(rand, base, amount)


def frame(img, inset, color):
    px = img.load()
    w, h = img.size
    c = hexc(color) if isinstance(color, str) else color
    for x in range(inset, w - inset):
        px[x, inset] = c
        px[x, h - 1 - inset] = c
    for y in range(inset, h - inset):
        px[inset, y] = c
        px[w - 1 - inset, y] = c


def stud(img, cx, cy):
    px = img.load()
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            c = GOLD_LIGHT if dx == -1 and dy == -1 else (GOLD_DARK if dx == 1 or dy == 1 else GOLD)
            px[cx + dx, cy + dy] = hexc(c)


# ------------------------------------------------------------------------------------------------ frames

def window():
    """Leather-bound parchment page with gold studs; border 10."""
    size = 64
    rand = random.Random(11)
    img = canvas(size, size)
    px = img.load()
    for y in range(size):
        for x in range(size):
            edge = min(x, y, size - 1 - x, size - 1 - y)
            if edge == 0:
                px[x, y] = hexc(OUTLINE)
            elif edge < 8:
                c = noisy(rand, LEATHER if edge > 1 else LEATHER_DARK, 0.06)
                if edge == 4 and (x + y) % 3 == 0:
                    c = shade(hexc("#C8A878"), 0.9)  # stitching
                px[x, y] = c
            elif edge == 8:
                px[x, y] = hexc(GOLD_DARK)
            elif edge == 9:
                px[x, y] = shade(hexc(PARCHMENT), 0.82)
            else:
                f = 0.9 + 0.01 * min(edge - 9, 10)
                px[x, y] = shade(noisy(rand, PARCHMENT, 0.03), f)
    for cx, cy in ((4, 4), (size - 5, 4), (4, size - 5), (size - 5, size - 5)):
        stud(img, cx, cy)
    return img


def panel():
    """Recessed parchment area inside a window; border 4."""
    size = 32
    rand = random.Random(12)
    img = canvas(size, size)
    parchment_fill(img, 0, 0, size, size, rand, base="#DCCB9C")
    frame(img, 0, "#9C8A68")
    px = img.load()
    for x in range(1, size - 1):
        px[x, 1] = shade(hexc("#9C8A68"), 1.15)
    return img


def hud_panel():
    """Translucent dark panel with a thin gold rule; border 4."""
    size = 32
    img = canvas(size, size)
    px = img.load()
    for y in range(size):
        for x in range(size):
            edge = min(x, y, size - 1 - x, size - 1 - y)
            if edge == 0:
                px[x, y] = (20, 12, 6, 170)
            elif edge == 1:
                px[x, y] = hexc(GOLD_DARK, 210)
            else:
                px[x, y] = (28, 18, 10, 165)
    return img


def toast():
    """Toast background, 160x32; border 6."""
    w, h = 160, 32
    rand = random.Random(13)
    img = canvas(w, h)
    px = img.load()
    for y in range(h):
        for x in range(w):
            edge = min(x, y, w - 1 - x, h - 1 - y)
            if edge == 0:
                px[x, y] = hexc(OUTLINE)
            elif edge < 4:
                px[x, y] = noisy(rand, LEATHER, 0.06)
            elif edge == 4:
                px[x, y] = hexc(GOLD_DARK)
            else:
                px[x, y] = noisy(rand, PARCHMENT, 0.03)
    return img


def button(state):
    """Wooden button; border 3. state: normal, highlighted, disabled, pressed."""
    w, h = 64, 20
    rand = random.Random(14)
    img = canvas(w, h)
    px = img.load()
    top, bottom = {
        "normal": ("#7A5232", "#4E3019"),
        "highlighted": ("#9A6B40", "#62401F"),
        "disabled": ("#6B6258", "#4A4440"),
        "pressed": ("#4E3019", "#6B4528"),
    }[state]
    t, b = hexc(top), hexc(bottom)
    for y in range(h):
        f = y / (h - 1)
        base = tuple(int(t[i] * (1 - f) + b[i] * f) for i in range(3)) + (255,)
        for x in range(w):
            px[x, y] = shade(base, 1.0 + rand.uniform(-0.04, 0.04))
    frame(img, 0, OUTLINE)
    edge = GOLD if state == "highlighted" else ("#8A8178" if state == "disabled" else GOLD_DARK)
    frame(img, 1, edge)
    for x in range(2, w - 2):
        px[x, 2] = shade(px[x, 2], 1.18)
    return img


def tab(selected):
    """Tab on top of a window; border 4."""
    w, h = 32, 20
    rand = random.Random(15)
    img = canvas(w, h)
    px = img.load()
    for y in range(h):
        for x in range(w):
            corner = (x < 2 and y < 2) or (x > w - 3 and y < 2)
            if corner:
                continue
            if x == 0 or x == w - 1 or y == 0:
                px[x, y] = hexc(OUTLINE)
            elif x == 1 or x == w - 2 or y == 1:
                px[x, y] = hexc(GOLD if selected else GOLD_DARK)
            elif selected:
                px[x, y] = noisy(rand, PARCHMENT, 0.03)
            else:
                px[x, y] = noisy(rand, LEATHER, 0.06)
    return img


def scroller(track):
    w, h = 6, 16
    img = canvas(w, h)
    px = img.load()
    for y in range(h):
        for x in range(w):
            edge = min(x, y, w - 1 - x, h - 1 - y)
            if track:
                px[x, y] = hexc("#9C8A68") if edge == 0 else hexc("#C9B58C")
            else:
                px[x, y] = hexc(OUTLINE) if edge == 0 else hexc(GOLD if edge > 1 else GOLD_DARK)
    return img


def slot():
    img = canvas(18, 18)
    px = img.load()
    for y in range(18):
        for x in range(18):
            if x == 0 or y == 0:
                px[x, y] = hexc("#8A7656")
            elif x == 17 or y == 17:
                px[x, y] = hexc("#F4EAD0")
            else:
                px[x, y] = hexc("#CDBA90")
    return img


def divider():
    w, h = 64, 3
    img = canvas(w, h)
    px = img.load()
    for x in range(w):
        fade = min(x, w - 1 - x) / 10.0
        a = int(255 * min(1.0, fade))
        px[x, 0] = hexc(GOLD_DARK, a)
        px[x, 1] = hexc(GOLD, a)
        px[x, 2] = hexc(GOLD_DARK, a // 2)
    return img


def banner():
    """Red ribbon with forked ends for announcements; borders left/right 20, top/bottom 6."""
    w, h = 128, 32
    rand = random.Random(16)
    img = canvas(w, h)
    px = img.load()
    red, red_dark = hexc("#8E1B1B"), hexc("#5E0F0F")
    for y in range(h):
        for x in range(w):
            # forked tails
            cut = 10 - abs(y - h // 2) * 10 // (h // 2)
            if x < cut or x > w - 1 - cut:
                continue
            edge_y = min(y, h - 1 - y)
            if edge_y == 0:
                px[x, y] = hexc(OUTLINE)
            elif edge_y in (2, 3):
                px[x, y] = hexc(GOLD if edge_y == 2 else GOLD_DARK)
            else:
                base = red_dark if edge_y == 1 else red
                px[x, y] = shade(base, 1.0 + rand.uniform(-0.05, 0.05))
    return img


def bar(fill):
    w, h = 32, 6
    img = canvas(w, h)
    px = img.load()
    for y in range(h):
        for x in range(w):
            edge = min(x, y, w - 1 - x, h - 1 - y)
            if edge == 0:
                px[x, y] = hexc(OUTLINE)
            elif fill:
                px[x, y] = (255, 255, 255, 255) if y > 1 else (255, 255, 255, 255)
            else:
                px[x, y] = hexc("#2A1C12", 200)
    return img


