def icon(art, palette):
    rows = art.strip("\n").split("\n")
    img = canvas(16, 16)
    px = img.load()
    for y, row in enumerate(rows[:16]):
        for x, ch in enumerate(row[:16]):
            if ch in palette:
                px[x, y] = hexc(palette[ch])
    return img


def main():
    write(window(), "window", nine(64, 64, 10))
    write(panel(), "panel", nine(32, 32, 4))
    write(hud_panel(), "hud_panel", nine(32, 32, 4))
    write(toast(), "toast", nine(160, 32, 6))
    for state in ("normal", "highlighted", "disabled", "pressed"):
        write(button(state), "button" if state == "normal" else "button_" + state, nine(64, 20, 3))
    write(tab(False), "tab", nine(32, 20, 4))
    write(tab(True), "tab_selected", nine(32, 20, 4))
    write(scroller(False), "scroller", nine(6, 16, 2))
    write(scroller(True), "scroller_track", nine(6, 16, 2))
    write(slot(), "slot")
    write(divider(), "divider", {"type": "stretch"})
    write(banner(), "banner", nine(128, 32, {"left": 20, "top": 6, "right": 20, "bottom": 6}))
    write(bar(False), "bar_background", nine(32, 6, 1))
    write(bar(True), "bar_fill", nine(32, 6, 1))
    for name, (art, palette) in ICONS.items():
        write(icon(art, palette), "icon/" + name)
    print("GUI sprites written to", SPRITES)


if __name__ == "__main__":
    main()
